def merge_sorted_streams(*streams):
    import heapq

    # Iterator that yields (key, value) pairs from a single stream,
    # keeping only the last occurrence of each key.
    def last_occurrence(stream):
        last = {}
        for k, v in stream:
            last[k] = v
        # stream is already sorted by key, so we can iterate in order
        for k in sorted(last):
            yield (k, last[k])

    # Wrap each input stream with the last‑occurrence filter.
    wrapped = [last_occurrence(s) for s in streams]

    # Build a min‑heap of the current items from each iterator.
    heap = []
    for idx, it in enumerate(wrapped):
        try:
            k, v = next(it)
            heapq.heappush(heap, (k, v, idx))
        except StopIteration:
            pass  # empty stream

    while heap:
        k, v, src = heapq.heappop(heap)
        yield (k, v)

        # Pull the next item from the same source iterator.
        try:
            nk, nv = next(wrapped[src])
            heapq.heappush(heap, (nk, nv, src))
        except StopIteration:
            pass
